<?php

namespace App\Helpers;

class MetaBannerHelper
{
    /**
     * Ensure the high-resolution Tokenweb3 Network institutional social banner exists on disk.
     * Generates the image directly from verified base64 payload to eliminate binary Git bloat.
     */
    public static function ensureMetaBannerExists(): void
    {
        $targets = [
            public_path('temp/images/meta.png'),
            base_path('temp/images/meta.png'),
            public_path('themes/ecx/assets/images/meta.png'),
            base_path('themes/ecx/assets/images/meta.png'),
        ];

        $needsWrite = false;
        foreach ($targets as $target) {
            if (!file_exists($target) || filesize($target) < 1000 || filesize($target) > 500000) {
                $needsWrite = true;
                break;
            }
        }

        if (!$needsWrite) {
            return;
        }

        $payload = '';

        $binary = base64_decode($payload);
        if (!$binary) {
            return;
        }

        foreach ($targets as $target) {
            $dir = dirname($target);
            if (!is_dir($dir)) {
                @mkdir($dir, 0755, true);
            }
            @file_put_contents($target, $binary);
        }
    }
}